<?php use App\Core\Security; ?>
<?php foreach($changes as $c):?><section class="panel"><div class="panel-header"><h2><?=Security::e($c['path'])?></h2><p><?=Security::e($c['framework'])?> · <?=$c['changed']?'Änderungen vorhanden':'Keine Änderung'?></p></div><?php if($c['changed']):?><div class="diff-grid"><div><h3>Aktuell</h3><pre><?=Security::e($c['old'])?></pre></div><div><h3>Geplant</h3><pre><?=Security::e($c['new'])?></pre></div></div><?php endif;?></section><?php endforeach;?><div class="toolbar"><a href="/servers/<?=$server_id?>" class="btn btn-secondary">Zurück</a><form method="post" action="/servers/<?=$server_id?>/sync" data-confirm="Änderungen jetzt auf den Server schreiben?"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><button class="btn btn-primary">Änderungen übertragen</button></form></div>
